CREATE TABLE flash_sale_release_job (id BIGINT NOT NULL AUTO_INCREMENT,request_id VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,activity_id BIGINT NOT NULL,user_id BIGINT NOT NULL,idempotency_digest BINARY(32) NOT NULL,reserved_at DATETIME(6) NOT NULL,reason VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,status VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'pending',attempts INT NOT NULL DEFAULT 0,next_attempt_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),lease_until DATETIME(6) NULL,last_error_code VARCHAR(48) CHARACTER SET ascii COLLATE ascii_bin NULL,completed_at DATETIME(6) NULL,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),PRIMARY KEY(id),CONSTRAINT uk_flash_sale_release_job_request UNIQUE(request_id),KEY idx_flash_sale_release_job_due(status,next_attempt_at,id),KEY idx_flash_sale_release_job_expired(status,lease_until,id),KEY idx_flash_sale_release_job_activity(activity_id),KEY idx_flash_sale_release_job_user(user_id),CONSTRAINT ck_flash_sale_release_job_request CHECK(REGEXP_LIKE(request_id,'^fsr_[1-9a-z][0-9a-z]{0,12}_[a-f0-9]{32}$','c')),CONSTRAINT ck_flash_sale_release_job_reason CHECK(reason IN ('technical_rollback','final_guard','payment_expired','admin_repair')),CONSTRAINT ck_flash_sale_release_job_status CHECK(status IN ('pending','leased','done')),CONSTRAINT ck_flash_sale_release_job_attempts CHECK(attempts>=0),CONSTRAINT ck_flash_sale_release_job_lifecycle CHECK((status='pending' AND lease_until IS NULL AND completed_at IS NULL) OR (status='leased' AND lease_until IS NOT NULL AND completed_at IS NULL AND attempts>0) OR (status='done' AND lease_until IS NULL AND completed_at IS NOT NULL AND attempts>0)),CONSTRAINT fk_flash_sale_release_job_activity FOREIGN KEY(activity_id) REFERENCES flash_sale_activity(id) ON DELETE RESTRICT,CONSTRAINT fk_flash_sale_release_job_user FOREIGN KEY(user_id) REFERENCES user_account(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARACTER SET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
